#!/usr/bin/env node

/*
# 运行调试器

如果玩家临时目录不存在 WuKongDebugApp 目录，或其目录中的 Package.json 文件的版本与当前版本不一致, 则解压 WuKongDebugApp.zip 到玩家临时目录.
然后运行目录中的 WuKongDebugApp.exe 文件.

注意, 应当从脚本执行路径的上一层,寻找 WuKongDeubgApp.zip 和 Package.json , 而不是从程序启动位置.

*/

const fs = require('fs');
const path = require('path');
const { execFile } = require('child_process');
const AdmZip = require('adm-zip');
const os = require('os');

// 获取脚本所在目录的上一层目录
const parentDir = path.dirname(__dirname);
const debugAppZip = path.join(parentDir, 'WuKongDebugApp.zip');
const packageJson = path.join(parentDir, 'Package.json');

// 获取临时目录中的调试器目录
const tempDir = path.join(os.tmpdir(), 'WuKongDebugApp');
const tempPackageJson = path.join(tempDir, 'Package.json');

// 检查调试器是否需要更新
async function needUpdate() {
    // 如果临时目录不存在,需要更新
    if (!fs.existsSync(tempDir)) {
        return true;
    }

    // 如果临时目录中的 Package.json 不存在,需要更新  
    if (!fs.existsSync(tempPackageJson)) {
        return true;
    }

    // 比较版本号
    const currentVersion = JSON.parse(fs.readFileSync(packageJson)).version;
    const tempVersion = JSON.parse(fs.readFileSync(tempPackageJson)).version;

    return currentVersion !== tempVersion;
}

// 解压调试器
function extractDebugApp() {
    // 添加文件存在检查
    if (!fs.existsSync(debugAppZip)) {
        throw new Error(`调试器压缩包不存在: ${debugAppZip}`);
    }

    // 确保目标目录存在
    if (!fs.existsSync(tempDir)) {
        fs.mkdirSync(tempDir, { recursive: true });
    }

    console.log("正在解压悟空调试器...");
    try {
        const zip = new AdmZip(debugAppZip);
        zip.extractAllTo(tempDir, true);
        console.log("解压完成");

        // 拷贝 Package.json 到目标目录
        fs.copyFileSync(packageJson, tempPackageJson);

    } catch (error) {
        throw new Error(`解压调试器失败: ${error.message}\n源文件: ${debugAppZip}`);
    }
}

// 运行调试器
function runDebugger() {
    const debuggerExe = path.join(tempDir, 'WuKongDebugApp.exe');

    // 添加文件存在检查
    if (!fs.existsSync(debuggerExe)) {
        throw new Error(`调试器程序不存在: ${debuggerExe}`);
    }

    console.log("正在悟空启动调试器:", debuggerExe);

    execFile(debuggerExe, [process.cwd()], (error) => {
        if (error) {
            console.error('运行调试器失败:', error);
        }
    });
}

// 主函数
async function main() {
    try {
        if (await needUpdate()) {
            await extractDebugApp();
        }
        runDebugger();
    } catch (error) {
        console.error('启动调试器失败:', error);
        // 输出更详细的错误信息
        if (error.stack) {
            console.error('错误堆栈:', error.stack);
        }
    }
}

main();
